// Convierte el aviso de error de n8n en una línea de registro. No guarda datos de la ejecución
// (pueden traer imágenes o información del lote), solo qué falló y dónde.
const e = $input.first().json;
const linea = {
  fecha: new Date().toISOString(),
  flujo: e.workflow && e.workflow.name,
  flujoId: e.workflow && e.workflow.id,
  ejecucion: e.execution && e.execution.id,
  nodo: e.execution && e.execution.lastNodeExecuted,
  mensaje: String((e.execution && e.execution.error && e.execution.error.message) || '').slice(0, 500),
};
const texto = `[${linea.fecha}] ${linea.flujo} falló en "${linea.nodo}": ${linea.mensaje} (ejecución ${linea.ejecucion})`;
const binario = await this.helpers.prepareBinaryData(Buffer.from(JSON.stringify(linea) + '\n', 'utf8'), 'errores.log', 'text/plain');
return [{ json: { ...linea, texto }, binary: { data: binario } }];
